{"command":"python - <<'PY'
import zipfile, shutil, os, copy, re, math
from lxml import etree
from datetime import datetime
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Border, Side, Alignment
from openpyxl.utils import get_column_letter
from openpyxl.worksheet.table import Table, TableStyleInfo
from openpyxl.comments import Comment

os.makedirs('output', exist_ok=True)
SRC='documents/turn-2-redline-meridian.docx'
OUT='output/turn-3-redline-gmra.docx'
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
R='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
CT='http://schemas.openxmlformats.org/package/2006/content-types'
qn=lambda tag: f'{{{W}}}{tag}'
ns={'w':W,'r':R}

def copy_rpr(p):
    r = p.find('.//'+qn('r'))
    if r is not None:
        rp=r.find(qn('rPr'))
        if rp is not None: return copy.deepcopy(rp)
    rp=etree.Element(qn('rPr'))
    rf=etree.SubElement(rp,qn('rFonts')); rf.set(qn('ascii'),'Times New Roman'); rf.set(qn('hAnsi'),'Times New Roman')
    sz=etree.SubElement(rp,qn('sz')); sz.set(qn('val'),'22')
    return rp

def set_text(p, text, bold=False, italic=False):
    pPr=p.find(qn('pPr'))
    for child in list(p):
        if child is not pPr: p.remove(child)
    r=etree.SubElement(p,qn('r'))
    rp=copy_rpr(p)
    if bold: etree.SubElement(rp,qn('b'))
    if italic: etree.SubElement(rp,qn('i'))
    r.append(rp)
    t=etree.SubElement(r,qn('t'))
    if text[:1].isspace() or text[-1:].isspace(): t.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
    t.text=text

def text_of(p):
    return ''.join((e.text or '') for e in p.iter() if e.tag==qn('t'))

def clear_children(p):
    pPr=p.find(qn('pPr'))
    for child in list(p):
        if child is not pPr: p.remove(child)

def add_run(parent, text, deleted=False, rpr=None):
    r=etree.SubElement(parent,qn('r'))
    if rpr is not None: r.append(copy.deepcopy(rpr))
    t=etree.SubElement(r,qn('delText') if deleted else qn('t'))
    if text[:1].isspace() or text[-1:].isspace(): t.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
    t.text=text

def set_tracked(p, old, new, author='Pryor, Ashworth & Gelb LLP'):
    pPr=p.find(qn('pPr'))
    clear_children(p)
    now='2025-04-18T09:00:00Z'
    if old:
        d=etree.SubElement(p,qn('del')); d.set(qn('id'),'9000'); d.set(qn('author'),author); d.set(qn('date'),now)
        add_run(d,old,deleted=True,rpr=copy_rpr(p))
    ins=etree.SubElement(p,qn('ins')); ins.set(qn('id'),'9001'); ins.set(qn('author'),author); ins.set(qn('date'),now)
    add_run(ins,new,deleted=False,rpr=copy_rpr(p))

def accept_all(root):
    # Accept every Turn 2 change before applying Turn 3 treatment.
    changes=list(root.xpath('.//w:body//w:del|.//w:body//w:ins',namespaces=ns))
    for c in changes:
        parent=c.getparent(); idx=parent.index(c)
        if c.tag==qn('del'):
            parent.remove(c)
        else:
            parent.remove(c)
            for k,ch in enumerate(list(c)):
                parent.insert(idx+k,ch)

def find_p(ps, prefix=None, contains=None):
    for p in ps:
        s=text_of(p)
        if prefix is not None and s.startswith(prefix): return p
        if contains is not None and contains in s: return p
    return None

def idx_of(ps,p): return ps.index(p)

def new_p_like(p, text):
